-- Keep today's existing goals intact; start the 100-goal rotation at the next UTC reset.
begin;
create table academy_progression_private.daily_catalog (
 id text primary key,position integer not null unique check(position between 0 and 99),title text not null,
 description text not null,metric text not null check(metric in ('correct','answers','sessions','accurate','perfect','modes','filters','comeback','improve','accurate_correct','balanced')),
 target integer not null check(target>0),xp integer not null check(xp between 25 and 250),
 game_mode text check(game_mode in ('study_test','matching','speed','blaster')),
 code_filter text check(code_filter in ('penal','hs','vehicle')),
 min_accuracy integer not null default 0 check(min_accuracy between 0 and 100),min_answers integer not null default 5 check(min_answers>=5),
 practice_path text not null check(practice_path in ('/study/test','/games/matching','/games/speed','/games/blaster')),category text not null
);
alter table academy_progression_private.daily_catalog enable row level security;
create table academy_progression_private.rotation_config (
 singleton boolean primary key default true check(singleton), starts_on date not null
);
alter table academy_progression_private.rotation_config enable row level security;
insert into academy_progression_private.rotation_config(starts_on) values((now() at time zone 'UTC')::date+1);
