/blaster","category":"Code Blaster \u00b7 Vehicle Code","position":88},{"id":"daily_blaster_vehicle_perfect","title":"Perfect traffic run","description":"Finish one Code Blaster session without a mistake with Vehicle Code selected. Each session must include at least five answers.","metric":"perfect","target":1,"xp":100,"game_mode":"blaster","code_filter":"vehicle","min_accuracy":0,"min_answers":5,"practice_path":"/games/blaster","category":"Code Blaster \u00b7 Vehicle Code","position":89},{"id":"daily_change_pace","title":"Change of pace","description":"Complete a session in two different practice modes. Every session must include at least five answers.","metric":"modes","target":2,"xp":80,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":90},{"id":"daily_versatile","title":"Versatile cadet","description":"Complete sessions in three different practice modes. Every session must include at least five answers.","metric":"modes","target":3,"xp":110,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":91},{"id":"daily_across_codes","title":"Across the codes","description":"Complete sessions using two different specific code sets: Penal, Health & Safety, or Vehicle. Mixed All Codes sessions do not count. Every session must include at least five answers.","metric":"filters","target":2,"xp":80,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":92},{"id":"daily_full_sweep","title":"Full code sweep","description":"Complete a session in each specific code set: Penal, Health & Safety, and Vehicle. Every session must include at least five answers.","metric":"filters","target":3,"xp":110,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":93},{"id":"daily_bounce_back","title":"Bounce back","description":"After a session below 80% accuracy, finish another at 80% or better in the same mode and code set today. Every session must include at least five answers.","metric":"comeback","target":1,"xp":100,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":94},{"id":"daily_raise_bar","title":"Raise the bar","description":"Improve your accuracy by at least 20 percentage points over an earlier session in the same mode and code set today. Every session must include at least five answers.","metric":"improve","target":1,"xp":100,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":95},{"id":"daily_accurate_depth","title":"Accuracy in depth","description":"Get 20 correct answers in sessions that each finish at 80% accuracy or better. Every session must include at least five answers.","metric":"accurate_correct","target":20,"xp":100,"game_mode":null,"code_filter":null,"min_accuracy":80,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":96},{"id":"daily_double_precision","title":"Double precision","description":"Finish two sessions at 90% accuracy or better. Every session must include at least five answers.","metric":"accurate","target":2,"xp":110,"game_mode":null,"code_filter":null,"min_accuracy":90,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":97},{"id":"daily_two_clean","title":"Two clean runs","description":"Finish two sessions without a mistake. Every session must include at least five answers.","metric":"perfect","target":2,"xp":120,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":98},{"id":"daily_balanced","title":"Balanced briefing","description":"Get at least 10 correct answers in each of two specific code sets: Penal, Health & Safety, or Vehicle. Every session must include at least five answers.","metric":"balanced","target":2,"xp":100,"game_mode":null,"code_filter":null,"min_accuracy":0,"min_answers":5,"practice_path":"/study/test","category":"Variety & improvement","position":99}]$catalog$::jsonb);
alter table academy_progression_private.events add column game_mode text,add column code_filter text,add column incorrect integer not null default 0 check(incorrect>=0);
update academy_progression_private.events e set game_mode=h.mode,code_filter=h.filter,incorrect=greatest(0,h.incorrect)
 from public.game_attempt_history h where h.id=e.attempt_id;
create or replace function academy_progression_private.record_attempt() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if new.correct>=0 and new.incorrect>=0 and new.correct+new.incorrect between 5 and 1000
 and new.mode in ('study_test','matching','speed','blaster') and public.get_active_class_id(new.user_id) is not null then
  insert into academy_progression_private.events(attempt_id,user_id,correct,incorrect,game_mode,code_filter)
  values(new.id,new.user_id,new.correct,new.incorrect,new.mode,new.filter) on conflict do nothing;
 end if;
 return new;
end $$;
create function academy_progression_private.daily_for_date(p_day date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare first_day date; day_index integer; result jsonb;
begin
 select starts_on into first_day from academy_progression_private.rotation_config;
 if p_day<first_day then
  return '[{"id":"daily_sessions","title":"Complete two practice sessions","description":"Finish two practice tests or solo games, with at least five answers each.","metric":"sessions","target":2,"xp":60,"min_answers":5,"min_accuracy":0,"practice_path":"/study/test","category":"Any practice"},{"id":"daily_correct","title":"Answer 20 questions correctly","description":"Get 20 correct answers across completed practice tests or solo games.","metric":"correct","target":20,"xp":80,"min_answers":5,"min_accuracy":0,"practice_path":"/study/test","category":"Any practice"}]'::jsonb;
 end if;
 day_index:=(p_day-first_day)%50;
 -- Multiplication by 37 is a permutation of all 100 positions, so there are no repeats within a cycle.
 select jsonb_agg(to_jsonb(c) order by slot) into result
 from generate_series(0,1) slot join academy_progression_private.daily_catalog c on c.position=((day_index*2+slot)*37)%100;
 return result;
end $$;
create function academy_progression_private.challenges_at(u uuid,p_day date) returns jsonb
language sql stable security definer set search_path='' as $$
 with catalog as (
 select d.*, 'daily'::text as cadence,p_day as start_date from jsonb_to_recordset(academy_progression_private.daily_for_date(p_day)) as d(id text,title text,description text,metric text,target int,xp int,game_mode text,code_filter text,min_accuracy int,min_answers int,practice_path text,category text)
 union all
 select 'weekly_sessions','Complete ten practice sessions','Finish ten practice tests or solo games, with at least five answers each.','sessions',10,250,null,null,0,5,'/study/test','Weekly practice','weekly',date_trunc('week',p_day::timestamp)::date
 union all
 select 'weekly_days','Practice on three different days','Complete a qualifying session on three different UTC days this week.','days',3,200,null,null,0,5,'/study/test','Weekly consistency','weekly',date_trunc('week',p_day::timestamp)::date
 ), all_events as (
 select e.*,e.correct+e.incorrect as answers,100.0*e.correct/nullif(e.correct+e.incorrect,0) as accuracy
 from academy_progression_private.events e where e.user_id=u
 and e.recorded_at>=(date_trunc('week',p_day::timestamp) at time zone 'UTC')
 and e.recorded_at<((p_day+1)::timestamp at time zone 'UTC')
 ), counted as (
 select c.*,coalesce((select case c.metric
 when 'correct' then coalesce(sum(e.correct),0)
 when 'answers' then coalesce(sum(e.answers),0)
 when 'sessions' then count(*)
 when 'days' then count(distinct (e.recorded_at at time zone 'UTC')::date)
 when 'accurate' then count(*) filter(where e.accuracy>=c.min_accuracy)
 when 'perfect' then count(*) filter(where e.incorrect=0)
 when 'modes' then count(distinct e.game_mode)
 when 'filters' then count(distinct e.code_filter) filter(where e.code_filter in ('penal','hs','vehicle'))
 when 'accurate_correct' then coalesce(sum(e.correct) filter(where e.accuracy>=c.min_accuracy),0)
 when 'balanced' then (select count(*) from (select q.code_filter from all_events q where q.recorded_at>=(c.start_date::timestamp at time zone 'UTC') and q.code_filter in ('penal','hs','vehicle') group by q.code_filter having sum(q.correct)>=10) by_code)
 when 'comeback' then count(*) filter(where e.accuracy>=80 and exists(select 1 from all_events q where q.recorded_at>=(c.start_date::timestamp at time zone 'UTC') and q.game_mode=e.game_mode and q.code_filter=e.code_filter and (q.recorded_at,q.attempt_id)<(e.recorded_at,e.attempt_id) and q.accuracy<80))
 when 'improve' then count(*) filter(where exists(select 1 from all_events q where q.recorded_at>=(c.start_date::timestamp at time zone 'UTC') and q.game_mode=e.game_mode and q.code_filter=e.code_filter and (q.recorded_at,q.attempt_id)<(e.recorded_at,e.attempt_id) and e.accuracy-q.accuracy>=20))
 else 0 end
 from all_events e where e.recorded_at>=(c.start_date::timestamp at time zone 'UTC')
 and e.answers>=c.min_answers and (c.game_mode is null or e.game_mode=c.game_mode) and (c.code_filter is null or e.code_filter=c.code_filter)),0) as progress
 from catalog c
 ) select jsonb_agg(jsonb_build_object('id',id,'cadence',cadence,'title',title,'description',description,'target',target,'xp',xp,'category',category,'practicePath',case
 when metric='modes' then coalesce((select route from (values('study_test','/study/test',1),('matching','/games/matching',2),('speed','/games/speed',3),('blaster','/games/blaster',4)) options(mode,route,priority) where not exists(select 1 from all_events e where e.game_mode=options.mode and e.recorded_at>=(c.start_date::timestamp at time zone 'UTC')) order by priority limit 1),'/study/test')
 when metric in ('comeback','improve') then coalesce((select case e.game_mode when 'matching' then '/games/matching' when 'speed' then '/games/speed' when 'blaster' then '/games/blaster' else '/study/test' end from all_events e where e.recorded_at>=(c.start_date::timestamp at time zone 'UTC') and e.accuracy<80 order by e.accuracy,e.attempt_id limit 1),'/study/test')
 else practice_path end,'codeFilter',case
 when metric in ('filters','balanced') then coalesce((select code from (values('penal',1),('hs',2),('vehicle',3)) options(code,priority) where (select coalesce(sum(case when c.metric='balanced' then e.correct else 1 end),0) from all_events e where e.code_filter=options.code and e.recorded_at>=(c.start_date::timestamp at time zone 'UTC'))<case when c.metric='balanced' then 10 else 1 end order by priority limit 1),'penal')
 when metric in ('comeback','improve') then (select e.code_filter from all_events e where e.recorded_at>=(c.start_date::timestamp at time zone 'UTC') and e.accuracy<80 order by e.accuracy,e.attempt_id limit 1)
 else code_filter end,
 'progress',least(progress,target),'claimed',exists(select 1 from academy_progression_private.claims cl where cl.user_id=u and cl.challenge=c.id and cl.period_start=c.start_date),
 'resetsAt',(start_date+case when cadence='daily' then 1 else 7 end)::timestamp at time zone 'UTC') order by cadence,id)
 from counted c
$$;
create or replace function public.get_academy_progression() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d date:=(now() at time zone 'UTC')::date; total bigint; starts date;
begin
 if u is null or not daily_reward_private.is_eligible(u) then raise exception 'Join an active class to earn progression';end if;
 total:=academy_progression_private.total_xp(u);
 select starts_on into starts from academy_progression_private.rotation_config;
 return jsonb_build_object('totalXp',total,'level',academy_progression_private.level(u),'challenges',academy_progression_private.challenges_at(u,d),
 'dailyCatalogSize',100,'dailyCycleDays',50,'dailyRotationStartsAt',starts::timestamp at time zone 'UTC','serverDate',d);
end $$;
-- Claiming still resolves only today's active challenge IDs, with server-selected XP and dates.
revoke all on all tables in schema academy_progression_private from public,anon,authenticated;
revoke all on all functions in schema academy_progression_private from public,anon,authenticated;
revoke all on function public.get_academy_progression() from public,anon;
grant execute on function public.get_academy_progression() to authenticated;
notify pgrst,'reload schema';
commit;
